const b = $json.body ?? $json;
const src = b.lead ?? b;
const email = String(src.email ?? '').trim().toLowerCase();
const website = String(src.website ?? src.company_website ?? '').trim();
let domain = website.replace(/^https?:\/\//i, '').split('/')[0];
if (!domain && email.includes('@')) {const candidate=email.split('@')[1];if(!['gmail.com','googlemail.com','outlook.com','hotmail.com','live.com','yahoo.com','aol.com','icloud.com','proton.me','protonmail.com'].includes(candidate))domain=candidate;}
domain = domain.toLowerCase().replace(/^www\./, '');
const subject = String(src.subject ?? b.subject ?? '');
let companyNameHint = String(src.company_name_hint ?? '').trim();
if (!companyNameHint) {
  const subjectMatch = subject.match(/(?:draft|feature|story|piece|article)(?:\s+(?:for|on))?\s+(.+?)\s*$/i);
  companyNameHint = subjectMatch?.[1]?.trim() ?? '';
}
const lead = {
  ...src,
  email: email,
  company_name_hint: companyNameHint,
  email_account: String(src.email_account ?? b.email_account ?? ''),
  reply_to_uuid: String(src.reply_to_uuid ?? b.reply_to_uuid ?? ''),
  subject: subject
};
const callbackUrl = b.callback_url ?? 'https://n8n.example.com/webhook/audit-complete';
const body = { domain: domain, lead: lead, company_name: companyNameHint, offer_mode: b.offer_mode || 'feature_plus_audit', options: { fixture: Boolean(b.options?.fixture) }, callback_url: callbackUrl };
return [{ json: { domain: domain, research_blocker: !/^[a-z0-9.-]+\.[a-z][a-z0-9-]+$/i.test(domain) ? 'verified_company_website_needed' : '', lead: lead, callback_url: callbackUrl, request_body: body } }];
